import React, { useEffect, useRef, useState } from "react";
import { motion, useInView } from "framer-motion";
import { STATS } from "./Content";

// Floating decorative element
const FloatingElement = ({ delay, duration, size, top, left, right }) => (
  <motion.div
    className="absolute pointer-events-none"
    style={{
      width: size,
      height: size,
      top,
      left,
      right,
      background: "radial-gradient(circle, rgba(212, 175, 55, 0.3) 0%, transparent 70%)",
      borderRadius: "50%",
      filter: "blur(20px)",
    }}
    animate={{
      y: [0, -20, 0],
      scale: [1, 1.1, 1],
      opacity: [0.3, 0.5, 0.3],
    }}
    transition={{
      duration,
      delay,
      repeat: Infinity,
      ease: "easeInOut",
    }}
  />
);

function Counter({ to, suffix, index }) {
  const [val, setVal] = useState(0);
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-100px" });
  const started = useRef(false);

  useEffect(() => {
    if (isInView && !started.current) {
      started.current = true;
      const duration = 1800;
      const start = performance.now();
      const tick = (now) => {
        const p = Math.min(1, (now - start) / duration);
        const eased = 1 - Math.pow(1 - p, 3);
        setVal(Math.round(to * eased));
        if (p < 1) requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    }
  }, [isInView, to]);

  return (
    <motion.span
      ref={ref}
      className="serif inline-block"
      style={{ fontSize: 56, color: "#d4af37", fontWeight: 400 }}
      initial={{ opacity: 0, scale: 0.5 }}
      animate={isInView ? { opacity: 1, scale: 1 } : {}}
      transition={{ delay: index * 0.1, duration: 0.5, type: "spring", stiffness: 100 }}
    >
      {val.toLocaleString()}{suffix}
    </motion.span>
  );
}

// Stat card animation
const statCardVariants = {
  hidden: { opacity: 0, y: 30 },
  visible: (i) => ({
    opacity: 1,
    y: 0,
    transition: { delay: i * 0.15, duration: 0.5, ease: "easeOut" }
  }),
  hover: {
    y: -8,
    boxShadow: "0 16px 40px rgba(212,175,55,0.25), 0 0 30px rgba(212,175,55,0.1)",
    borderColor: "rgba(212, 175, 55, 0.6)",
    transition: { duration: 0.25, ease: "easeOut" }
  }
};

export default function About() {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-100px" });

  return (
    <section id="about" className="relative px-6 md:px-12 lg:px-32 py-20 md:py-28 overflow-hidden" style={{ background: "#fdf8ed" }}>

      {/* Floating decorative elements */}
      <FloatingElement delay={0} duration={6} size="200px" top="10%" left="5%" />
      <FloatingElement delay={2} duration={8} size="150px" top="60%" right="8%" />
      <FloatingElement delay={4} duration={7} size="100px" top="30%" right="15%" />

      {/* Decorative gold lines */}
      <motion.div
        className="absolute top-0 left-0 w-full h-px"
        style={{
          background: "linear-gradient(90deg, transparent, rgba(212, 175, 55, 0.3), transparent)"
        }}
        initial={{ scaleX: 0 }}
        whileInView={{ scaleX: 1 }}
        viewport={{ once: true }}
        transition={{ duration: 1.5, ease: "easeOut" }}
      />

      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-16 items-start relative z-10">
        <motion.div
          className="lg:col-span-5"
          initial={{ opacity: 0, x: -50 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true, margin: "-100px" }}
          transition={{ duration: 0.7, ease: "easeOut" }}
        >
          <div className="flex items-center gap-3 mb-6">
            <motion.div
              className="w-12 h-px"
              style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }}
              initial={{ width: 0 }}
              whileInView={{ width: 48 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6 }}
            />
            <span className="overline font-bold tracking-[0.4em]">The Legacy</span>
          </div>
          <h2 style={{ fontSize: "clamp(40px, 5vw, 64px)", lineHeight: 1.05, color: "#1a080a", fontFamily: "Outfit, sans-serif", fontWeight: 800 }}>
            A fabric house from Ludhiana, adorning India's grandest <span style={{ color: "#d4af37", fontWeight: 800 }}>celebrations</span>.
          </h2>

          {/* Decorative element */}
          <motion.div
            className="mt-8 flex items-center gap-4"
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ delay: 0.3, duration: 0.5 }}
          >
            <div className="flex gap-2">
              {[...Array(5)].map((_, i) => (
                <motion.div
                  key={i}
                  className="w-2 h-2 rounded-full"
                  style={{ background: "#d4af37" }}
                  animate={{
                    scale: i === 2 ? [1, 1.3, 1] : [1, 1, 1],
                    opacity: i === 2 ? [0.6, 1, 0.6] : [0.4, 0.4, 0.4]
                  }}
                  transition={{ duration: 2, repeat: Infinity, delay: i * 0.1 }}
                />
              ))}
            </div>
            <span className="text-sm" style={{ color: "rgba(26,8,10,0.5)" }}>Since 2012</span>
          </motion.div>
        </motion.div>

        <div className="lg:col-span-6 lg:col-start-8" ref={ref}>
          <motion.p
            className="text-lg font-semibold"
            style={{ color: "rgba(26,8,10,0.8)", lineHeight: 1.8, maxWidth: 560 }}
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6, delay: 0.1 }}
          >
            For over a decade, D SAJAWAT has been the quiet hand behind some of the country's most exquisite wedding venues. We source, finish and supply premium fabrics - drapes, covers, sashes, florals.
          </motion.p>

          <motion.p
            className="mt-5 text-lg"
            style={{ color: "rgba(26,8,10,0.7)", lineHeight: 1.7, maxWidth: 580, fontWeight: 450 }}
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6, delay: 0.2 }}
          >
            From a single roll to a banquet's worth - we deliver across India, on time, in finish.
          </motion.p>

          <motion.div
            className="mt-10 grid grid-cols-2 gap-6"
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, margin: "-50px" }}
            variants={{
              hidden: { opacity: 0 },
              visible: { opacity: 1, transition: { staggerChildren: 0.15, delayChildren: 0.3 } }
            }}
          >
            {STATS.map((s, i) => (
              <motion.div
                key={s.label}
                className="p-6 rounded-xl text-center stat-card relative overflow-hidden"
                custom={i}
                variants={statCardVariants}
                whileHover="hover"
              >
                {/* Background gradient */}
                <div
                  className="absolute inset-0 opacity-30"
                  style={{
                    background: "linear-gradient(135deg, rgba(212, 175, 55, 0.1) 0%, transparent 100%)"
                  }}
                />

                {/* Animated border */}
                <motion.div
                  className="absolute inset-0 rounded-xl pointer-events-none"
                  style={{
                    background: "linear-gradient(90deg, transparent, rgba(212, 175, 55, 0.3), transparent)",
                    backgroundSize: "200% 100%",
                  }}
                  animate={{
                    backgroundPosition: ["200% 0", "-200% 0"],
                  }}
                  transition={{ duration: 3, repeat: Infinity, ease: "linear" }}
                />

                <Counter to={s.value} suffix={s.suffix} index={i} />
                <motion.div
                  className="mt-2 overline relative z-10"
                  style={{ color: "rgba(26,8,10,0.6)" }}
                  initial={{ opacity: 0 }}
                  whileInView={{ opacity: 1 }}
                  viewport={{ once: true }}
                  transition={{ delay: 0.5 + i * 0.1 }}
                >
                  {s.label}
                </motion.div>

                {/* Gold shimmer effect on hover */}
                <div
                  className="absolute inset-0 pointer-events-none opacity-0 hover:opacity-100 transition-opacity duration-300"
                  style={{
                    background: "linear-gradient(135deg, transparent 40%, rgba(212, 175, 55, 0.05) 50%, transparent 60%)",
                  }}
                />
              </motion.div>
            ))}
          </motion.div>
        </div>
      </div>
    </section>
  );
}
